window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-191c36f735f7b363"]={"versions": [{"id": "FIG-191c36f735f7b363", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / PDU-Layout zur Darstellung des Bit- und Byteaufbaus einer gesicherten Protokolldateneinheit (Secured I-PDU) im Kontext des AUTOSAR-Basissoftwaremoduls SecOC (Secure Onboard Communication).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Struktur umfasst drei sequenzielle Felder innerhalb der Gesamteinheit:</p>\n<ul class=\"fig-list\"><li><code>Authentic I-PDU</code>: Nutzdatenbereich bzw. ursprüngliche, zu schützende Protokolldateneinheit (blau hinterlegt).\n</li><li><code>Freshness Value</code>: Frischewert / Replay-Schutzwert (orange hinterlegt).\n</li><li><code>Authenticator</code>: Kryptografischer Authentifizierungswert (z. B. MAC, orange hinterlegt).\n</li></ul>\n<p class=\"fig-p\">Eine unterliegende geschweifte Klammer fasst alle drei Bestandteile zur Gesamteinheit zusammen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische PDU-Serialisierungsreihenfolge von links nach rechts (niederwertigste zu höherwertige Offset-Positionen):</p>\n<ol class=\"fig-list\"><li>Payload der Authentic I-PDU bildet den Beginn des Übertragungsrahmens.\n</li><li>Der Freshness Value schließt unmittelbar an die Authentic I-PDU an.\n</li><li>Der Authenticator schließt unmittelbar an den Freshness Value an und bildet das Ende des Rahmens.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Reihenfolge der Datenfelder in der gesicherten PDU. Sender- und Empfängerkomponenten der SecOC müssen die Serialisierung und Deserialisierung exakt nach diesem Layout vornehmen: Die Authentic I-PDU geht dem Authentifizierungsanhang voran, gefolgt von Frischewert und Authenticator.</p>"}, {"id": "FIG-41b6bd7d77abf902", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / PDU-Layout zur Darstellung des Bit- und Byteaufbaus einer gesicherten Protokolldateneinheit (Secured I-PDU) im Kontext des AUTOSAR-Basissoftwaremoduls SecOC (Secure Onboard Communication).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Struktur umfasst vier sequenzielle Felder innerhalb der als <code>Secured I-PDU</code> beschrifteten Gesamteinheit:</p>\n<ul class=\"fig-list\"><li><code>Secured I-PDU Header (optional)</code>: Optionaler Header am Beginn der PDU (blau hinterlegt).\n</li><li><code>Authentic I-PDU</code>: Nutzdatenbereich bzw. ursprüngliche, zu schützende Protokolldateneinheit (blau hinterlegt).\n</li><li><code>Freshness Value (optional)</code>: Optionaler Frischewert zur Replay-Absicherung (orange hinterlegt).\n</li><li><code>Authenticator</code>: Kryptografischer Authentifizierungswert (z. B. MAC, orange hinterlegt).\n</li></ul>\n<p class=\"fig-p\">Eine unterliegende geschweifte Klammer mit der Beschriftung <code>Secured I-PDU</code> fasst die gesamte Feldsequenz zusammen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische PDU-Serialisierungsreihenfolge von links nach rechts (niederwertigste zu höherwertige Offset-Positionen):</p>\n<ol class=\"fig-list\"><li><code>Secured I-PDU Header (optional)</code>: Sofern konfiguriert, steht der Header an erster Stelle.\n</li><li><code>Authentic I-PDU</code>: Nutzdatenbereich folgt unmittelbar auf den Header bzw. bildet ohne Header den Beginn.\n</li><li><code>Freshness Value (optional)</code>: Sofern im Payload übertragen, folgt der Frischewert direkt auf die Authentic I-PDU.\n</li><li><code>Authenticator</code>: Schließt als finales Sicherheitsfeld unmittelbar an den Frischewert (bzw. bei dessen Entfall an die Authentic I-PDU) an.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation des PDU-Aufbaus für SecOC. Die Felder <code>Secured I-PDU Header</code> und <code>Freshness Value</code> sind explizit als optional deklariert. Implementierungen müssen konfigurierbar unterstützen, ob ein Header vorangestellt und ob der Freshness Value ganz oder teilweise innerhalb der übertragenen Secured I-PDU übermittelt wird, während der Authenticator obligatorisch das Ende markiert.</p>"}, {"id": "FIG-358c891880c0c4e3", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / PDU-Layout zur Darstellung des Bit- und Byteaufbaus einer gesicherten Protokolldateneinheit (Secured I-PDU) im Kontext des AUTOSAR-Basissoftwaremoduls SecOC (Secure Onboard Communication).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Struktur umfasst vier sequenzielle Felder innerhalb der als <code>Secured I-PDU</code> beschrifteten Gesamteinheit:</p>\n<ul class=\"fig-list\"><li><code>Secured I-PDU Header (optional)</code>: Optionaler Header am Beginn der PDU (blau hinterlegt).\n</li><li><code>Authentic I-PDU</code>: Nutzdatenbereich bzw. ursprüngliche, zu schützende Protokolldateneinheit (blau hinterlegt).\n</li><li><code>Freshness Value (optional)</code>: Optionaler Frischewert zur Replay-Absicherung (orange hinterlegt).\n</li><li><code>Authenticator</code>: Kryptografischer Authentifizierungswert (z. B. MAC, orange hinterlegt).\n</li></ul>\n<p class=\"fig-p\">Eine unterliegende geschweifte Klammer mit der Beschriftung <code>Secured I-PDU</code> fasst die gesamte Feldsequenz zusammen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische PDU-Serialisierungsreihenfolge von links nach rechts (niederwertigste zu höherwertige Offset-Positionen):</p>\n<ol class=\"fig-list\"><li><code>Secured I-PDU Header (optional)</code>: Sofern konfiguriert, steht der Header an erster Stelle.\n</li><li><code>Authentic I-PDU</code>: Nutzdatenbereich folgt unmittelbar auf den Header bzw. bildet ohne Header den Beginn.\n</li><li><code>Freshness Value (optional)</code>: Sofern im Payload übertragen, folgt der Frischewert direkt auf die Authentic I-PDU.\n</li><li><code>Authenticator</code>: Schließt als finales Sicherheitsfeld unmittelbar an den Frischewert (bzw. bei dessen Entfall an die Authentic I-PDU) an.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation des PDU-Aufbaus für SecOC. Die Felder <code>Secured I-PDU Header</code> und <code>Freshness Value</code> sind explizit als optional deklariert. Implementierungen müssen konfigurierbar unterstützen, ob ein Header vorangestellt und ob der Freshness Value ganz oder teilweise innerhalb der übertragenen Secured I-PDU übermittelt wird, während der Authenticator obligatorisch das Ende markiert.</p>"}], "trans": [{"from": "FIG-191c36f735f7b363", "to": "FIG-41b6bd7d77abf902", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Vor der <code>Authentic I-PDU</code> ist das Element <code>Secured I-PDU Header (optional)</code> eingefügt.\n</li><li>Unter dem Element <code>Freshness Value</code> ist der Zusatz <code>(optional)</code> ergänzt.\n</li><li>Unterhalb der geschweiften Klammer ist die Beschriftung <code>Secured I-PDU</code> ergänzt.\n</li></ul>"}, {"from": "FIG-41b6bd7d77abf902", "to": "FIG-358c891880c0c4e3", "fr": "R21-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
